parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "reply": {
      "type": "string",
      "description": "A short professional response to the customer"
    },
    "intent": {
      "type": "string",
      "enum": [
        "pricing",
        "sales",
        "support",
        "human_handoff",
        "general"
      ],
      "description": "Use human_handoff whenever the customer asks for a human, agent, representative, manager, or real person"
    },
    "requires_human": {
      "type": "boolean",
      "description": "Must be true only when intent is human_handoff"
    }
  },
  "required": [
    "reply",
    "intent",
    "requires_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
const input = $json;

const customerMessage = String(
  $("Webhook").first().json.body?.message ?? ""
).trim();

let rawOutput =
  input.output ??
  input.text ??
  input.response ??
  input.content ??
  "";

let parsed = {};

if (
  rawOutput &&
  typeof rawOutput === "object" &&
  !Array.isArray(rawOutput)
) {
  parsed = rawOutput;
} else {
  let rawText = String(rawOutput ?? "").trim();

  rawText = rawText
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {
    parsed = JSON.parse(rawText);
  } catch {
    parsed = {
      reply: rawText,
    };
  }
}

if (
  parsed.output &&
  typeof parsed.output === "object"
) {
  parsed = parsed.output;
}

const asksForHuman =
  /\b(human|agent|representative|manager|team member|real person|sales representative|speak to someone|connect me)\b/i.test(
    customerMessage
  );

const isPricing =
  /\b(price|pricing|cost|charges|package|plan|subscription|quotation|quote)\b/i.test(
    customerMessage
  );

const isSales =
  /\b(buy|purchase|order|book|demo|demonstration|service|sales)\b/i.test(
    customerMessage
  );

const isSupport =
  /\b(error|issue|problem|support|help|not working|failed|failure|technical)\b/i.test(
    customerMessage
  );

let intent = String(parsed.intent ?? "").toLowerCase();

const allowedIntents = [
  "pricing",
  "sales",
  "support",
  "human_handoff",
  "general",
];

if (!allowedIntents.includes(intent)) {
  if (asksForHuman) {
    intent = "human_handoff";
  } else if (isPricing) {
    intent = "pricing";
  } else if (isSales) {
    intent = "sales";
  } else if (isSupport) {
    intent = "support";
  } else {
    intent = "general";
  }
}

let requiresHuman =
  parsed.requires_human === true ||
  String(parsed.requires_human).toLowerCase() === "true";

if (asksForHuman) {
  intent = "human_handoff";
  requiresHuman = true;
}

if (intent === "human_handoff") {
  requiresHuman = true;
}

let reply = String(parsed.reply ?? "").trim();

if (!reply) {
  if (asksForHuman) {
    reply =
      "Thank you. I’ll pass your request to a human team member who will assist you shortly.";
  } else {
    reply =
      "Thank you for contacting us. Please provide a little more detail so we can assist you.";
  }
}

return {
  json: {
    output: {
      reply,
      intent,
      requires_human: requiresHuman,
    },
  },
};

const documents = $input.all();

const knowledgeContext = documents
  .map((item) =>
    item.json.pageContent ??
    item.json.document?.pageContent ??
    item.json.content ??
    ""
  )
  .filter(Boolean)
  .join("\n\n");

return [
  {
    json: {
      knowledge_context:
        knowledgeContext ||
        "No relevant approved business information was found."
    }
  }
];
